package edu.pe.cibertec.saibm.libro.domain;
import static org.assertj.core.api.Assertions.*; import java.util.UUID; import org.junit.jupiter.api.Test; import edu.pe.cibertec.saibm.libro.domain.exception.InvalidBookException; import edu.pe.cibertec.saibm.libro.domain.model.Book;
class BookDomainTest { @Test void normalizesMetadataWithoutStock(){var b=Book.create(UUID.randomUUID()," Java ",null," Ada ",null);assertThat(b.title()).isEqualTo("Java");assertThat(b.description()).isEmpty();assertThat(b.author()).isEqualTo("Ada");assertThat(b.active()).isTrue();} @Test void updatesAndDeactivatesLifecycle(){var b=Book.create(UUID.randomUUID(),"Java","old","Ada","x");assertThat(b.update("Java 2","new","Grace","y").active()).isTrue();assertThat(b.deactivate().active()).isFalse();} @Test void rejectsBlankTitle(){assertThatThrownBy(()->Book.create(UUID.randomUUID()," ","","Ada","")).isInstanceOf(InvalidBookException.class);} }
